'use client';
import {useState} from 'react';
import {shiftDate,statuses,type ManualEvent} from '@/lib/vendor-calendar/model';
import type {VendorServiceRow} from '@/lib/repositories/vendorsRepository';
const input='w-full rounded-lg border ui-border ui-surface p-3';
export function EventEditor({initial,onChange,onCancel,onSave,services,warnings}:{initial:ManualEvent;onChange:(d:ManualEvent)=>void;onCancel:()=>void;onSave:()=>Promise<void>;services:VendorServiceRow[];warnings:string[]}){
 const [busy,setBusy]=useState(false),[error,setError]=useState('');
 const d=initial;function change(p:Partial<ManualEvent>){onChange({...d,...p});}
 const zones=Array.from(new Set(['UTC',...Intl.supportedValuesOf('timeZone'),d.timezone].filter(Boolean)));
 return <form aria-label="External event editor" className="space-y-4 rounded-xl border ui-border ui-surface p-5" onSubmit={async e=>{e.preventDefault();setError('');if(d.end_date===d.date&&d.end_time<=d.start_time){setError('End time must follow start time. Select ends next day for an overnight event.');return;}setBusy(true);try{await onSave();}catch(err){setError(err instanceof Error?err.message:'Unable to save event.');}finally{setBusy(false);}}}>
 <div><h2 className="text-xl font-semibold">{d.version?'Edit external event':'Add external event'}</h2><p className="text-sm ui-muted">Private to your business. No client messages are sent.</p></div>
 <label className="grid gap-1">Event name<input required maxLength={200} className={input} value={d.name} onChange={e=>change({name:e.target.value})}/></label>
 <div className="grid gap-3 sm:grid-cols-2"><label>Date<input required type="date" className={input} value={d.date} onChange={e=>change({date:e.target.value,end_date:d.end_date!==d.date?shiftDate(e.target.value,1):e.target.value})}/></label><label>Status<select className={input} value={d.status} onChange={e=>change({status:e.target.value as ManualEvent['status']})}>{statuses.map(s=><option key={s}>{s}</option>)}</select></label><label>Start time<input required type="time" className={input} value={d.start_time.slice(0,5)} onChange={e=>change({start_time:e.target.value})}/></label><label>End time<input required type="time" className={input} value={d.end_time.slice(0,5)} onChange={e=>change({end_time:e.target.value})}/></label></div>
 <label className="flex gap-2"><input type="checkbox" checked={d.end_date!==d.date} onChange={e=>change({end_date:e.target.checked?shiftDate(d.date,1):d.date})}/>Ends next day{d.end_date!==d.date?' ('+d.end_date+')':''}</label>
 <label className="grid gap-1">Event timezone<select required className={input} value={d.timezone} onChange={e=>change({timezone:e.target.value})}><option value="">Choose the business-local timezone</option>{zones.map(z=><option key={z}>{z}</option>)}</select></label><p className="text-xs ui-muted">Dates and times stay as entered. Events can last up to 24 hours. Repeated daylight-saving hours use the timezone’s standard-time occurrence.</p>
 <details open={!!d.version}><summary className="cursor-pointer py-2 font-semibold">Client, location and preparation</summary><div className="grid gap-3 pt-3 sm:grid-cols-2">{(['event_type','client_name','client_contact','location'] as const).map((key,i)=><label key={key}>{['Event type','Client name','Private client contact','Location'][i]}<input className={input} value={d[key]} maxLength={key==='location'?1000:key==='client_contact'?500:200} onChange={e=>change({[key]:e.target.value})}/></label>)}<label className="sm:col-span-2">Associated service<select className={input} value={d.service_id||''} onChange={e=>change({service_id:e.target.value||null})}><option value="">No service selected</option>{services.map(s=><option key={s.id} value={s.id}>{s.service_name}{!s.active?' (inactive)':''}</option>)}</select></label><label className="sm:col-span-2">Notes<textarea rows={4} maxLength={10000} className={input} value={d.notes} onChange={e=>change({notes:e.target.value})}/></label></div>
 <h3 className="mt-4 font-semibold">Preparation tasks</h3>{d.tasks.map((t,i)=><div key={i} className="my-2 flex items-center gap-2"><input aria-label={'Complete '+(t.title||'task '+(i+1))} type="checkbox" checked={t.done} onChange={e=>change({tasks:d.tasks.map((x,j)=>j===i?{...x,done:e.target.checked}:x)})}/><input aria-label={'Task '+(i+1)} required maxLength={300} className={input} value={t.title} onChange={e=>change({tasks:d.tasks.map((x,j)=>j===i?{...x,title:e.target.value}:x)})}/><button type="button" aria-label={'Remove task '+(i+1)} onClick={()=>change({tasks:d.tasks.filter((_,j)=>j!==i)})}>Remove</button></div>)}<button type="button" className="mt-2 underline" disabled={d.tasks.length>=100} onClick={()=>change({tasks:[...d.tasks,{title:'',done:false}]})}>Add preparation task</button></details>
 {warnings.map(w=><p key={w} className="text-sm text-amber-800">{w}</p>)}{error&&<p role="alert" className="text-red-700">{error}</p>}<div className="flex gap-3"><button className="hub-primary" disabled={busy}>{busy?'Saving…':'Save event'}</button><button type="button" className="hub-button" disabled={busy} onClick={onCancel}>Cancel</button></div></form>;
}
